def canonical(source):
 return re.sub(r'^_private\..*?\.[0-9]+\.','',source)

def normalized(ir,row,names):
 from audit_kernel import _ir_definition_body
 body=_ir_definition_body(ir,row['symbol'])
 if body is None:raise Core0Error('Paper2 emitted body missing')
 body=re.sub(r'@switch\.table\.'+re.escape(row['symbol'])+r'(?![A-Za-z0-9_.$-])','@switch.table.'+canonical(row['source']),body)
 rebound=re.sub(r'@([^ (]+)',lambda m:'@'+names.get(m[1],m[1]),body)
 return ' '.join(' '.join(line.split(';',1)[0].strip() for line in rebound.splitlines()).split())

def validate(ir,unit,*,optimized):
 cfg=unit.get('configuration');selected=cfg in EXPECTED and unit.get('role')=='kernel'
 rows={canonical(row['source']):row for row in unit.get('functions',[])}
 next_sources={source for source in rows if 'Next' in source and source.startswith(('Lemma.Platform.LemmaSim.','Lemma.Platform.Silicon.Binding','Lemma.Drivers.Paper.','Lemma.Kernel.Memory.AddressSpace.'))}
 if not selected:
  if next_sources:raise Core0Error('Paper2 successor declarations escape exact kernel deployment')
  return None
 want=EXPECTED[cfg]
 if next_sources!={source for source in want if 'Next' in source} or len(rows)!=len(unit['functions']):raise Core0Error('Paper2 complete successor declaration inventory differs')
 if unit.get('contract_version')!=('core0-kernel-v0.7' if 'product-next' in cfg else 'core0-kernel-v0.6'):raise Core0Error('Paper2 successor changed its Kernel6/7 privilege authority')
 names={row['symbol']:source for source,row in rows.items()};observed={}
 for source,(args,effects,digest) in want.items():
  row=rows.get(source)
  if row is None or row.get('args')!=args or row.get('effects')!=effects:raise Core0Error('Paper2 source signature/effects differ: '+source)
  if optimized and source!='Lemma.Platform.LemmaSim.DescriptorDTB.literalWordNext':continue
  expected=POST_LITERAL[cfg] if optimized else digest
  actual=hashlib.sha256(normalized(ir,row,names).encode()).hexdigest()
  if actual!=expected:raise Core0Error('Paper2 checked staging/discovery/owned-call/reset/boot authority differs: '+source)
  observed[source]=actual
 return {'contract_version':'lemma-paper-staging-v2','configuration':cfg,'stage_offset':3584,'bytes':512,'pre_or_post':'post' if optimized else 'pre','complete_body_identities':observed,'scope':'Checked compiled authority only; actual notebook/ROM Ready and performance require separate results'}
